const categories = ['small_talk','factual_questions','absurd_prompts','humor','irritation','disagreement','correction','praise','emotional_support','advice','urgency','relationship_sensitive','public_private','autobiographical_continuity','outdated_truth','unknown_information','memory_not_needed','irrelevant_memory','misunderstanding_repair','repeated_question','topic_switching','vulnerable_disclosure','refusal','boundary_setting','mixed_language','held_out_continuation','novel_situation'];
export const arseniySpeechBenchmarkV1 = Object.freeze(Array.from({ length: 60 }, (_, i) => { const category = categories[i % categories.length]; return Object.freeze({ id: `speech_v1_${String(i + 1).padStart(3, '0')}`, category, message: category === 'factual_questions' ? 'What is the current state?' : category === 'unknown_information' ? 'Do you know the answer?' : category === 'emotional_support' ? 'Мне тяжело.' : category === 'correction' ? 'Нет, это неправильно.' : 'Давай поговорим.', relationshipMode: i % 3 === 0 ? 'close' : 'public', expectedIntent: category === 'correction' ? 'correct' : category === 'emotional_support' ? 'reassure' : category === 'unknown_information' ? 'show_uncertainty' : undefined, memoryRequired: !['small_talk','memory_not_needed'].includes(category), prohibitedTaskAgentPhrases: ['Executing the requested action', 'progress report'] }); }));
